insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "b4f74d1d-4af8-53a4-966a-99439633f4f1", "status": "published", "metadata": {"sprint": "15B.4", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §8, տպագիր էջեր 26-28", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(1)"}}, "title_hy": "Ինչպե՞ս տարբերակել ատոմը, մոլեկուլը և քիմիական տարրը", "hint_1_hy": "Հաշվի՛ր՝ քանի՞ ատոմ է ներկայացված, և որոշի՛ր՝ դրանք միացա՞ծ են մեկ ընդհանուր մասնիկի մեջ, թե՞ ոչ։", "hint_2_hy": "Այնուհետև նայիր ատոմների տեսակներին. մոլեկուլը կարող է կազմված լինել և՛ նույն, և՛ տարբեր տեսակի ատոմներից, իսկ քիմիական տարրը նյութ է՝ կազմված միևնույն տեսակի ատոմներից։", "created_at": "2026-10-01T13:14:29.2027+00:00", "updated_at": "2026-10-05T13:29:12.49074+00:00", "strategy_hy": "Նախ պարզիր՝ նկարագրված է մեկ առանձին մասնիկ, միացած երկու կամ ավելի ատոմ, թե նյութ՝ կազմված միևնույն տեսակի ատոմներից։ Մեկ առանձին մասնիկը ատոմ է, միացած երկու կամ ավելի ատոմներից կազմված կայուն մասնիկը՝ մոլեկուլ, իսկ միևնույն տեսակի ատոմներից բաղկացած նյութը՝ քիմիական տարր։", "guide_version": 3, "item_template_id": "b3ab2ae5-4313-56b9-9918-4ee73992ec24", "worked_example_hy": "Օրինակ՝ H₂-ը մոլեկուլ է, որովհետև կազմված է իրար միացած երկու ջրածնի ատոմից։ Այն թեև կազմված է նույն տեսակի ատոմներից, սակայն «մոլեկուլ» և «քիմիական տարր» հասկացությունները նույնը չեն. առաջինը մասնիկ է, երկրորդը՝ նյութի տեսակ։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
